"""
Contract: perceive(observation_history) -> str must never raise, never return empty.
Produces a concise text summary of all non-background cells in the current grid observation,
plus the current active colour (inferred from the most recent click), plus hashes to ensure
uniqueness.  This output changes even when only the active colour changes (i.e., after a
movement), allowing the predictor to recover the hidden action.
"""

import json
import hashlib
from collections import Counter


def _compute_background(grid):
    """Return the most common colour in the grid (the background)."""
    counter = Counter()
    for row in grid:
        counter.update(row)
    return counter.most_common(1)[0][0]


def _summarize_non_background(grid, background):
    """Return sorted list "r,c:colour" for every non-background cell."""
    items = []
    for r, row in enumerate(grid):
        for c, colour in enumerate(row):
            if colour != background:
                items.append(f"{r},{c}:{colour}")
    items.sort()
    return items


def _parse_grid(obs: str):
    """Extract the 2D colour grid as list[list[str]] from the observation string."""
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end <= start:
        return None
    try:
        grid = json.loads(obs[start:end+2])
    except Exception:
        return None
    if not grid or not isinstance(grid, list) or not isinstance(grid[0], list):
        return None
    return grid


def _grid_hash(grid):
    """Return an MD5 hex digest of the grid's JSON representation."""
    return hashlib.md5(json.dumps(grid, separators=(',', ':')).encode()).hexdigest()[:12]


def _compute_active_color(observation_history, default="?"):
    """
    Infer the current active colour by scanning the history for the most recent
    click that added a new non-background cell.  The colour of that new cell is
    the active colour at that time.  If no change occurred in the last step, the
    active colour stays the same as the previous state's active colour.
    Returns a colour string (or default if unknown).
    """
    # We'll walk backwards until we find a change, but it's easier to process forward.
    active = default
    prev_grid = None
    prev_background = None
    for i, obs in enumerate(observation_history):
        grid = _parse_grid(obs)
        if grid is None:
            continue
        background = _compute_background(grid) if i == 0 else prev_background  # reuse if possible
        if prev_grid is not None:
            # Find cells in current grid that were not in prev_grid (non-background)
            new_cells = []
            for r, row in enumerate(grid):
                for c, colour in enumerate(row):
                    if colour != background:
                        # Check if this cell exists and has same colour in prev_grid
                        # (we assume grid dimensions are constant)
                        if r < len(prev_grid) and c < len(prev_grid[r]):
                            prev_colour = prev_grid[r][c]
                            if prev_colour == background or prev_colour != colour:
                                # It's new or recoloured -> this click's colour
                                new_cells.append(colour)
                        else:
                            # row/col out of previous bounds -> new cell
                            new_cells.append(colour)
            if new_cells:
                # Take the colour of the first new cell (usually there is exactly one)
                active = new_cells[0]
            # If no new cells, active remains unchanged
        prev_grid = grid
        prev_background = background
    return active


def perceive(observation_history: list[str]) -> str:
    if not observation_history:
        return "error: empty history"

    obs = observation_history[-1]
    grid = _parse_grid(obs)
    if grid is None:
        return "error: cannot parse grid"

    # Determine background
    try:
        background = _compute_background(grid)
    except Exception:
        background = "black"

    # Active colour inferred from history
    try:
        active_color = _compute_active_color(observation_history, "?")
    except Exception:
        active_color = "?"

    # Non-background cells
    try:
        items = _summarize_non_background(grid, background)
    except Exception:
        return f"BGRD:{background}|AC:{active_color}|error_collecting_cells"

    # Build base summary
    base = f"BGRD:{background}|"
    if not items:
        base += "empty"
    else:
        base += ";".join(items)

    # Hashes
    curr_hash = _grid_hash(grid)
    prev_hash = "?"
    if len(observation_history) >= 2:
        prev_obs = observation_history[-2]
        prev_grid = _parse_grid(prev_obs)
        if prev_grid is not None:
            prev_hash = _grid_hash(prev_grid)

    # Final string: active colour, hashes, then base
    summary = f"AC:{active_color}|PH:{prev_hash}|CH:{curr_hash}|{base}"

    # Enforce length <= 2000
    if len(summary) > 2000:
        # Truncate the non-background list if needed
        # Find start of list after "BGRD:..."
        bgr_start = summary.find("BGRD:")
        if bgr_start != -1:
            prefix_end = summary.find("|", bgr_start) + 1  # after first '|' of base
        else:
            prefix_end = len(summary)
        allowed = 2000 - prefix_end - 3
        if allowed > 0:
            summary = summary[:prefix_end] + summary[prefix_end:prefix_end+allowed] + "..."
        else:
            summary = summary[:1997] + "..."

    return summary

"""
Contract: perceive(observation_history: list[str]) -> str must never raise, never return empty.
Produces a concise text summary of all non-background cells in the current grid observation,
plus the current active colour (inferred from the most recent click), plus hashes,
a step counter, and the number of non-background cells.  The output changes when the
underlying grid changes (even if only the active colour changes), making the hidden action
recoverable from a window of consecutive summaries.
"""

import json
import hashlib
from collections import Counter


def _compute_background(grid):
    """Return the most common colour in the grid (the background)."""
    counter = Counter()
    for row in grid:
        counter.update(row)
    return counter.most_common(1)[0][0]


def _summarize_non_background(grid, background):
    """Return sorted list "r,c:colour" for every non-background cell."""
    items = []
    for r, row in enumerate(grid):
        for c, colour in enumerate(row):
            if colour != background:
                items.append(f"{r},{c}:{colour}")
    items.sort()  # sort by row then column (natural string order)
    return items


def _parse_grid(obs: str):
    """Extract the 2D colour grid as list[list[str]] from the observation string."""
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end <= start:
        return None
    try:
        grid = json.loads(obs[start:end + 2])
    except Exception:
        return None
    if not grid or not isinstance(grid, list) or not isinstance(grid[0], list):
        return None
    return grid


def _grid_hash(grid):
    """Return an MD5 hex digest (first 12 characters) of the grid's JSON representation."""
    return hashlib.md5(json.dumps(grid, separators=(',', ':')).encode()).hexdigest()[:12]


def _compute_active_color(observation_history):
    """
    Infer the current active colour by scanning the history for the most recent click.
    A click is detected by comparing consecutive grids: any cell that changes colour
    (including from background to non‑background) indicates a click, and the *new* colour
    is the active colour after that click.  Movements (no grid change) keep the active
    colour unchanged.
    Returns a colour string or "?" if no click has occurred yet.
    """
    if len(observation_history) < 2:
        return "?"

    # Iterate forward to track active colour
    active = "?"
    prev_grid = None
    for i, obs in enumerate(observation_history):
        grid = _parse_grid(obs)
        if grid is None:
            continue
        if prev_grid is not None:
            # check for any colour change (click)
            found_change = False
            for r, row in enumerate(grid):
                for c, colour in enumerate(row):
                    # ensure prev_grid has the same cell
                    if r < len(prev_grid) and c < len(prev_grid[r]):
                        prev_colour = prev_grid[r][c]
                        if colour != prev_colour:
                            # click changed the colour of this cell
                            active = colour
                            found_change = True
                            break
                    else:
                        # new row/col – treat as change (should not happen if grids same size)
                        active = colour
                        found_change = True
                        break
                if found_change:
                    break
        prev_grid = grid
    return active


def perceive(observation_history: list[str]) -> str:
    # Safety: never raise, never return empty.
    try:
        if not observation_history:
            return "error: empty history"

        obs = observation_history[-1]
        grid = _parse_grid(obs)
        if grid is None:
            return "error: cannot parse grid"

        # Determine background
        try:
            background = _compute_background(grid)
        except Exception:
            background = "black"

        # Active colour from entire history
        try:
            active_color = _compute_active_color(observation_history)
        except Exception:
            active_color = "?"

        # Step counter (0-based index of current observation in the history)
        step = len(observation_history) - 1

        # Non-background cells
        try:
            items = _summarize_non_background(grid, background)
        except Exception:
            return f"STEP:{step}|AC:{active_color}|error_collecting_cells"

        # Build base summary with size first
        base = f"size:{len(items)}|" + ("empty" if not items else ";".join(items))

        # Hashes
        curr_hash = _grid_hash(grid)
        prev_hash = "?"
        if len(observation_history) >= 2:
            prev_obs = observation_history[-2]
            prev_grid = _parse_grid(prev_obs)
            if prev_grid is not None:
                prev_hash = _grid_hash(prev_grid)

        # Final string: step, active colour, hashes, then base
        summary = f"STEP:{step}|AC:{active_color}|PH:{prev_hash}|CH:{curr_hash}|{base}"

        # Enforce length <= 2000
        if len(summary) > 2000:
            # Truncate the cell list if needed; keep all prefixes intact.
            # Find where the cell list begins (after "size:N|")
            size_prefix = "size:"
            size_pos = summary.find(size_prefix)
            if size_pos != -1:
                # Find the '|' after the size prefix
                list_start = summary.find("|", size_pos) + 1  # start of cell list or "empty"
            else:
                list_start = len(summary)
            allowed = 2000 - list_start - 3
            if allowed > 0:
                summary = summary[:list_start] + summary[list_start:list_start + allowed] + "..."
            else:
                summary = summary[:1997] + "..."

        return summary

    except Exception:
        # Final safety net – never raise, never return empty.
        return "perception_error"
